"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { attachMinecraftInput } from "./minecraft-input-paint"
import "./minecraft-input.css"

function Input({ className, type = "text", scale = 2, style, ref, ...props }:
  React.ComponentProps<"input"> & { scale?: 1 | 2 | 3 }) {
  const node = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => node.current!, [])
  React.useEffect(() => node.current ? attachMinecraftInput(node.current, scale) : undefined, [scale])
  return <input ref={node} type={type} data-slot="input" className={cn("mc-input", className)}
    style={{ "--mc-scale": scale, ...style } as React.CSSProperties} {...props} />
}
export { Input }

@layer theme, base, components, utilities;
@import "./minecraft-text-assets.css";
@layer components {
  .mc-input {
    --mc-pixel: calc(1px * var(--mc-scale, 2));
    display: inline-block;
    box-sizing: border-box;
    width: calc(200 * var(--mc-pixel));
    height: calc(20 * var(--mc-pixel));
    min-width: calc(9 * var(--mc-pixel));
    border: 0;
    border-radius: 0;
    outline: none;
    padding: 0 calc(4 * var(--mc-pixel));
    background-color: #000;
    background-image: var(--mc-input-image);
    background-size: 100% 100%;
    background-repeat: no-repeat;
    image-rendering: pixelated;
    font-family: "Minecraft Pilot 26.2", monospace;
    font-size: calc(8 * var(--mc-pixel));
    font-weight: 400;
    font-kerning: none;
    letter-spacing: 0;
    line-height: calc(8 * var(--mc-pixel));
    color: #e0e0e0;
    caret-color: #e0e0e0;
    cursor: text;
    opacity: 1;
  }
  .mc-input:disabled, .mc-input:read-only { color: #707070; caret-color: #707070; }
  .mc-input:disabled { cursor: not-allowed; }
  .mc-input[data-mc-bitmap="true"] { color: transparent; caret-color: transparent; -webkit-text-fill-color: transparent; }
  .mc-input[data-mc-bitmap="true"]::placeholder { color: transparent; -webkit-text-fill-color: transparent; }
  .mc-input[data-mc-bitmap="true"]::selection { background: transparent; color: transparent; -webkit-text-fill-color: transparent; }
  .mc-input::placeholder { opacity: 1; color: #555; }
}

import { minecraftInputAssets } from "./minecraft-input-assets"
import { minecraftGlyphs } from "./minecraft-font"

type Images = { normal: HTMLImageElement; highlighted: HTMLImageElement; alpha: Uint8ClampedArray }
let images: Promise<Images> | undefined
function loadImages() {
  return images ??= Promise.all(Object.values(minecraftInputAssets).map(src => new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image()
    image.onload = () => resolve(image)
    image.onerror = () => reject(new Error("Embedded Minecraft Input image could not load"))
    image.src = src
  }))).then(([normal, highlighted, atlas]) => {
    const canvas = document.createElement("canvas")
    canvas.width = canvas.height = 128
    const context = canvas.getContext("2d")!
    context.drawImage(atlas, 0, 0)
    return { normal, highlighted, alpha: context.getImageData(0, 0, 128, 128).data }
  })
}
const advance = (text: string) => Array.from(text).reduce((sum, char) => sum + (minecraftGlyphs[char.charCodeAt(0) - 32]?.[2] ?? 0), 0)
function trimToWidth(text: string, width: number, backwards = false) {
  let length = 0, used = 0
  const chars = backwards ? Array.from(text).reverse() : Array.from(text)
  for (const char of chars) {
    const next = minecraftGlyphs[char.charCodeAt(0) - 32]?.[2] ?? 0
    if (used + next > width) break
    used += next; length++
  }
  return backwards ? text.slice(text.length - length) : text.slice(0, length)
}
function scrollTo(text: string, start: number, position: number, width: number) {
  start = Math.min(start, text.length)
  const end = start + trimToWidth(text.slice(start), width).length
  if (position === start) start -= trimToWidth(text, width, true).length
  if (position > end) start += position - end
  else if (position <= start) start = position
  return Math.max(0, Math.min(text.length, start))
}
function field(context: CanvasRenderingContext2D, image: HTMLImageElement, width: number, height: number, scale: number) {
  const widths = [1, 198, 1], heights = [1, 18, 1]
  const destinationWidths = [scale, width - 2 * scale, scale], destinationHeights = [scale, height - 2 * scale, scale]
  for (let row = 0, sy = 0, dy = 0; row < 3; sy += heights[row], dy += destinationHeights[row++]) {
    for (let column = 0, sx = 0, dx = 0; column < 3; sx += widths[column], dx += destinationWidths[column++]) {
      for (let y = 0; y < destinationHeights[row]; y += heights[row] * scale) for (let x = 0; x < destinationWidths[column]; x += widths[column] * scale) {
        const w = Math.min(widths[column] * scale, destinationWidths[column] - x), h = Math.min(heights[row] * scale, destinationHeights[row] - y)
        context.drawImage(image, sx, sy, w / scale, h / scale, dx + x, dy + y, w, h)
      }
    }
  }
}
function text(context: CanvasRenderingContext2D, alpha: Uint8ClampedArray, value: string, x: number, y: number, ink: number, scale: number) {
  for (const shadow of [true, false]) {
    let offset = x
    const color = shadow ? Math.floor(ink / 4) : ink
    context.fillStyle = `rgb(${color},${color},${color})`
    for (const char of value) {
      const [gx, gy, width] = minecraftGlyphs[char.charCodeAt(0) - 32]
      if (char !== " ") for (let py = 0; py < 8; py++) for (let px = 0; px < 8; px++) {
        if (alpha[((gy + py) * 128 + gx + px) * 4 + 3]) context.fillRect((offset + px + Number(shadow)) * scale, (y + py + Number(shadow)) * scale, scale, scale)
      }
      offset += width
    }
  }
}

/** Paints a native input's background, retaining the actual editable DOM input. */
export function attachMinecraftInput(input: HTMLInputElement, initialScale: number) {
  const canvas = document.createElement("canvas")
  const context = canvas.getContext("2d", { willReadFrequently: true })!
  let cancelled = false, frame = 0, signature = "", start = 0, wasFocused = document.activeElement === input, focusedAt = Date.now(), previousValue = ""
  let loaded: Images
  const paint = () => {
    if (!loaded || cancelled) return
    const style = getComputedStyle(input)
    const scale = Number(style.getPropertyValue("--mc-scale")) || initialScale
    const width = input.clientWidth, height = input.clientHeight
    if (!width || !height) return
    const value = input.value
    const focused = document.activeElement === input
    if (focused && !wasFocused) focusedAt = Date.now()
    wasFocused = focused
    const blink = Math.floor((Date.now() - focusedAt) / 300) % 2 === 0
    const supported = ["text", "search", "url", "tel"].includes(input.type) && /^[\x20-\x7e]*$/.test(value + input.placeholder) && style.direction !== "rtl"
    if (input.dataset.mcBitmap !== String(supported)) input.dataset.mcBitmap = String(supported)
    const cursor = input.selectionDirection === "backward" ? input.selectionStart ?? value.length : input.selectionEnd ?? value.length
    const anchor = input.selectionDirection === "backward" ? input.selectionEnd ?? cursor : input.selectionStart ?? cursor
    if (previousValue !== value) { start = 0; previousValue = value }
    const nextSignature = JSON.stringify([width, height, scale, value, cursor, anchor, focused, blink && focused, input.disabled, input.readOnly, input.placeholder, input.maxLength, supported])
    if (nextSignature === signature) return
    signature = nextSignature
    canvas.width = width; canvas.height = height
    context.imageSmoothingEnabled = false
    field(context, focused && !input.disabled ? loaded.highlighted : loaded.normal, width, height, scale)
    if (supported) {
      const innerWidth = width / scale - 8
      start = scrollTo(value, start, cursor, innerWidth)
      const visible = trimToWidth(value.slice(start), innerWidth)
      const local = cursor - start, cursorInView = local >= 0 && local <= visible.length
      const ink = input.readOnly || input.disabled ? 112 : 224
      const y = Math.floor((height / scale - 8) / 2)
      const insert = cursor < value.length || (input.maxLength >= 0 && value.length >= input.maxLength)
      let cursorX = 4
      if (visible.length) {
        const prefix = cursorInView ? visible.slice(0, local) : visible
        text(context, loaded.alpha, prefix, 4, y, ink, scale)
        cursorX += advance(prefix) + 1
      }
      if (cursorInView && insert) cursorX--
      if (cursorInView && local < visible.length) text(context, loaded.alpha, visible.slice(local), cursorX, y, ink, scale)
      if (!visible.length && !focused && input.placeholder) text(context, loaded.alpha, input.placeholder, 4, y, 85, scale)
      const anchorLocal = Math.max(0, Math.min(visible.length, anchor - start))
      if (anchorLocal !== local) {
        const other = Math.min(width / scale, 4 + advance(visible.slice(0, anchorLocal)) - 1)
        const here = Math.min(width / scale, cursorX)
        const left = Math.max(0, Math.min(here, other) * scale), right = Math.min(width, Math.max(here, other) * scale)
        if (right > left) {
          const pixels = context.getImageData(left, (y - 1) * scale, right - left, 11 * scale)
          for (let i = 0; i < pixels.data.length; i += 4) { pixels.data[i] = 255 - pixels.data[i]; pixels.data[i + 1] = 255 - pixels.data[i + 1]; pixels.data[i + 2] = 255 }
          context.putImageData(pixels, left, (y - 1) * scale)
        }
      }
      if (focused && blink && cursorInView) {
        if (insert) { context.fillStyle = `rgb(${ink},${ink},${ink})`; context.fillRect(cursorX * scale, (y - 1) * scale, scale, 11 * scale) }
        else text(context, loaded.alpha, "_", cursorX, y, ink, scale)
      }
    }
    input.style.setProperty("--mc-input-image", `url("${canvas.toDataURL()}")`)
    input.dataset.mcReady = "true"
  }
  const tick = () => { paint(); if (!cancelled) frame = requestAnimationFrame(tick) }
  const focus = () => { wasFocused = true; focusedAt = Date.now(); signature = ""; paint() }
  const blur = () => { wasFocused = false; signature = ""; paint() }
  input.addEventListener("focus", focus)
  input.addEventListener("blur", blur)
  loadImages().then(result => { if (!cancelled) { loaded = result; tick() } }).catch(error => { if (!cancelled) { input.dataset.mcBitmap = "false"; console.error(error) } })
  return () => { cancelled = true; cancelAnimationFrame(frame); input.removeEventListener("focus", focus); input.removeEventListener("blur", blur) }
}
